import pytest

def clean_amount(raw):
    """Normalize a currency string like '$1,234.50' to a float."""
    if raw is None or raw == '':
        raise ValueError("amount missing")
    return float(raw.replace('$', '').replace(',', ''))

@pytest.fixture
def sample_rows():
    # Arrange: shared baseline data injected into tests by name
    return [{'amount': '$1,000.00'}, {'amount': '$2,500.50'}]

def test_clean_amount_sums(sample_rows):
    # Act
    total = sum(clean_amount(r['amount']) for r in sample_rows)
    # Assert
    assert total == 3500.50

@pytest.mark.parametrize("raw,expected", [
    ('$1,234.50', 1234.50),
    ('500', 500.0),
    ('$0', 0.0),
])
def test_clean_amount_parses(raw, expected):
    assert clean_amount(raw) == expected

def test_clean_amount_rejects_empty():
    with pytest.raises(ValueError, match="amount missing"):
        clean_amount('')
